// File: Core/Learn/LearnGlossary.swift
// Trading terms for the Learn glossary, sorted A–Z when shown.

import Foundation

extension LearnContent {
    static let glossary: [LearnGlossaryTerm] = [
        LearnGlossaryTerm(term: "Ask", definition: "The lowest price a seller will currently accept. You usually pay the ask when you buy at market."),
        LearnGlossaryTerm(term: "Assignment", definition: "When an option seller is required to fulfill the contract: sell the shares for a call, or buy them for a put."),
        LearnGlossaryTerm(term: "Averaging down", definition: "Buying more of something after its price falls, which lowers your average cost but adds to a losing position."),
        LearnGlossaryTerm(term: "Base currency", definition: "The first currency in a forex pair. In EUR/USD, the euro is the base currency."),
        LearnGlossaryTerm(term: "Bear market", definition: "A long period of falling prices, often defined as a drop of 20% or more from a recent high."),
        LearnGlossaryTerm(term: "Bid", definition: "The highest price a buyer will currently pay. You usually receive the bid when you sell at market."),
        LearnGlossaryTerm(term: "Blockchain", definition: "A shared public record of transactions that many computers keep in sync. Most cryptocurrencies run on one."),
        LearnGlossaryTerm(term: "Breakeven", definition: "The price at which a trade neither makes nor loses money, after costs such as premium or fees."),
        LearnGlossaryTerm(term: "Breakout", definition: "When price moves through a support or resistance level, often watched for a bigger move in that direction."),
        LearnGlossaryTerm(term: "Broker", definition: "A company that places your orders on the market and holds your account."),
        LearnGlossaryTerm(term: "Bull market", definition: "A long period of rising prices and generally positive sentiment."),
        LearnGlossaryTerm(term: "Call option", definition: "A contract that gives the buyer the right, but not the obligation, to buy 100 shares at the strike price before expiry."),
        LearnGlossaryTerm(term: "Callout", definition: "A trade idea shared in an Arkad community, usually with an entry, a stop and a target."),
        LearnGlossaryTerm(term: "Candlestick", definition: "A chart bar showing the open, high, low and close for one period of time."),
        LearnGlossaryTerm(term: "Cold wallet", definition: "A crypto wallet kept offline, such as a hardware device, which is harder to hack."),
        LearnGlossaryTerm(term: "Day trading", definition: "Opening and closing trades within the same day, without holding positions overnight."),
        LearnGlossaryTerm(term: "Delta", definition: "How much an option's price tends to change for a $1 move in the underlying stock."),
        LearnGlossaryTerm(term: "Diversification", definition: "Spreading money across different assets so one bad position doesn't sink the whole account."),
        LearnGlossaryTerm(term: "Dividend", definition: "A cash payment some companies make to shareholders, usually every quarter."),
        LearnGlossaryTerm(term: "Drawdown", definition: "How far an account has fallen from its highest value, shown in dollars or percent."),
        LearnGlossaryTerm(term: "Earnings", definition: "A company's quarterly results. Prices often move sharply when they're released."),
        LearnGlossaryTerm(term: "ETF", definition: "Exchange-traded fund: a basket of assets, such as an index, that trades like a single stock."),
        LearnGlossaryTerm(term: "Exchange", definition: "A marketplace where buyers and sellers are matched, such as the NYSE, Nasdaq or a crypto exchange."),
        LearnGlossaryTerm(term: "Expiry", definition: "The date an options contract ends. After it, the option can no longer be exercised."),
        LearnGlossaryTerm(term: "Fill", definition: "When your order is executed. A partial fill means only part of the order went through."),
        LearnGlossaryTerm(term: "FOMO", definition: "Fear of missing out: the urge to jump into a move because others are, often without a plan."),
        LearnGlossaryTerm(term: "Fractional share", definition: "Part of one share, which some brokers let you buy with a small dollar amount."),
        LearnGlossaryTerm(term: "Gap", definition: "When price opens well above or below the previous close, skipping the prices in between."),
        LearnGlossaryTerm(term: "Gas fee", definition: "A fee paid to process a transaction on some blockchains, such as Ethereum."),
        LearnGlossaryTerm(term: "Hot wallet", definition: "A crypto wallet connected to the internet, such as a phone app. Convenient, but more exposed."),
        LearnGlossaryTerm(term: "Implied volatility", definition: "The size of future moves the options market is pricing in. Higher implied volatility makes options more expensive."),
        LearnGlossaryTerm(term: "In the money", definition: "An option with intrinsic value: a call with a strike below the stock price, or a put with a strike above it."),
        LearnGlossaryTerm(term: "Index", definition: "A measure of a group of assets, such as the S&P 500, used to track a market."),
        LearnGlossaryTerm(term: "Intrinsic value", definition: "The part of an option's price it would be worth if exercised right now."),
        LearnGlossaryTerm(term: "Leverage", definition: "Using borrowed money to control a larger position. It magnifies gains and losses equally."),
        LearnGlossaryTerm(term: "Limit order", definition: "An order to buy or sell only at your chosen price or better. It may not fill."),
        LearnGlossaryTerm(term: "Liquidity", definition: "How easily you can buy or sell without moving the price much. Liquid markets have tight spreads."),
        LearnGlossaryTerm(term: "Long", definition: "Owning an asset because you expect its price to rise."),
        LearnGlossaryTerm(term: "Lot", definition: "A standard trade size in forex. A standard lot is 100,000 units, a mini lot 10,000 and a micro lot 1,000."),
        LearnGlossaryTerm(term: "Margin", definition: "Money borrowed from your broker to trade, or the deposit required to hold a leveraged position."),
        LearnGlossaryTerm(term: "Margin call", definition: "A demand from your broker to add money when your account falls below the required margin. Positions may be closed if you don't."),
        LearnGlossaryTerm(term: "Market cap", definition: "A company's total value: share price times the number of shares."),
        LearnGlossaryTerm(term: "Market order", definition: "An order to buy or sell right away at the best available price. Fast, but the price isn't guaranteed."),
        LearnGlossaryTerm(term: "Moving average", definition: "The average closing price over a set number of periods, drawn as a line to smooth out noise."),
        LearnGlossaryTerm(term: "Out of the money", definition: "An option with no intrinsic value: a call with a strike above the stock price, or a put with a strike below it."),
        LearnGlossaryTerm(term: "Paper trading", definition: "Practicing with simulated money so you can test a plan without risking real funds."),
        LearnGlossaryTerm(term: "Penny stock", definition: "A very low-priced, often thinly traded stock. Prone to big swings and manipulation."),
        LearnGlossaryTerm(term: "Pip", definition: "The standard unit of price movement in forex, usually 0.0001, or 0.01 for yen pairs."),
        LearnGlossaryTerm(term: "Portfolio", definition: "All the positions and cash you hold."),
        LearnGlossaryTerm(term: "Position size", definition: "How many shares, contracts, coins or units you hold in one trade."),
        LearnGlossaryTerm(term: "Pre-market", definition: "US stock trading before the regular session opens at 9:30 a.m. Eastern. Volume is usually thin."),
        LearnGlossaryTerm(term: "Premium", definition: "The price of an options contract, quoted per share. One contract usually covers 100 shares."),
        LearnGlossaryTerm(term: "Pump and dump", definition: "A scam where promoters hype a cheap asset to push its price up, then sell to the buyers they attracted."),
        LearnGlossaryTerm(term: "Put option", definition: "A contract that gives the buyer the right, but not the obligation, to sell 100 shares at the strike price before expiry."),
        LearnGlossaryTerm(term: "Quote currency", definition: "The second currency in a forex pair. In EUR/USD, prices are shown in US dollars."),
        LearnGlossaryTerm(term: "Resistance", definition: "A price area where selling has tended to stop rises."),
        LearnGlossaryTerm(term: "Revenge trading", definition: "Trading impulsively to win back a loss, usually with bigger size and less planning."),
        LearnGlossaryTerm(term: "Risk/reward", definition: "How much you could lose compared with how much you aim to make. Risking $1 to make $3 is 1:3."),
        LearnGlossaryTerm(term: "Seed phrase", definition: "A list of words that restores a crypto wallet. Anyone who has it controls your funds, so never share it."),
        LearnGlossaryTerm(term: "Short", definition: "Selling borrowed shares to profit if the price falls. Losses can grow without limit if it rises."),
        LearnGlossaryTerm(term: "Slippage", definition: "The difference between the price you expected and the price you actually got."),
        LearnGlossaryTerm(term: "Spread", definition: "The gap between the bid and the ask. It's a cost every time you trade."),
        LearnGlossaryTerm(term: "Stablecoin", definition: "A crypto token designed to hold a steady value, usually one US dollar. It can still lose its peg."),
        LearnGlossaryTerm(term: "Stop loss", definition: "An order that closes your position if price reaches a level you set, to limit the loss."),
        LearnGlossaryTerm(term: "Stop-limit order", definition: "A stop that becomes a limit order once triggered. It controls price but may not fill in a fast move."),
        LearnGlossaryTerm(term: "Strike price", definition: "The price at which an option lets you buy (call) or sell (put) the underlying."),
        LearnGlossaryTerm(term: "Support", definition: "A price area where buying has tended to stop falls."),
        LearnGlossaryTerm(term: "Swing trading", definition: "Holding trades for days to weeks to capture a single move."),
        LearnGlossaryTerm(term: "Take profit", definition: "An order or plan to close a trade once it reaches your target price."),
        LearnGlossaryTerm(term: "Theta", definition: "How much value an option tends to lose each day from the passing of time, all else equal."),
        LearnGlossaryTerm(term: "Ticker", definition: "The short code for an asset, such as AAPL for Apple or BTC for Bitcoin."),
        LearnGlossaryTerm(term: "Timeframe", definition: "The period each bar or candle on a chart covers, such as 5 minutes, 1 day or 1 week."),
        LearnGlossaryTerm(term: "Track record", definition: "A trader's history of results. On Arkad it's built from closed callouts."),
        LearnGlossaryTerm(term: "Trend", definition: "The general direction of price over time: up, down or sideways."),
        LearnGlossaryTerm(term: "Vega", definition: "How much an option's price tends to change when implied volatility moves by one point."),
        LearnGlossaryTerm(term: "Volatility", definition: "How much and how quickly a price moves. Higher volatility means bigger swings both ways."),
        LearnGlossaryTerm(term: "Volume", definition: "How many shares, contracts or coins traded in a period. It shows how much interest there is in a move."),
        LearnGlossaryTerm(term: "Watchlist", definition: "A list of symbols you follow so you can keep an eye on their prices."),
        LearnGlossaryTerm(term: "Win rate", definition: "The share of closed trades that made money. On its own it says nothing about how big wins and losses were.")
    ]
}
